import csv, json, os
period = PARAMS['period']
src = INPUT_DIRS[0]
files = {'erp': os.path.join(src, f'erp_export_{period}.csv'), 'crm': os.path.join(src, f'crm_export_{period}.csv')}
need = {'erp': {'invoice_id', 'customer', 'amount'}, 'crm': {'invoice_id', 'account_name', 'amount'}}
profile = {'ok': True, 'period': period}
for k, p in files.items():
    if not os.path.exists(p):
        profile['ok'] = False; profile[k] = 'missing'; continue
    with open(p, newline='', encoding='utf-8-sig') as f:
        r = csv.DictReader(f); rows = list(r)
    missing = sorted(need[k] - set(r.fieldnames or []))
    profile[k] = {'rows': len(rows), 'missing_columns': missing, 'total': round(sum(float(x['amount']) for x in rows), 2) if not missing else None}
    if missing: profile['ok'] = False
open(os.path.join(OUTPUT_DIR, f'input_profile_{period}.json'), 'w').write(json.dumps(profile, indent=1))
print(json.dumps(profile))
